175	+fn serialize_session(
176	+    session: &crate::sessions::SessionWithMessages,
177	+    fidelity: RestoreFidelity,
178	+) -> Result<Vec<RestoredFile>, AdapterError> {
179	+    let mut messages = session.messages.clone();
180	+    if fidelity == RestoreFidelity::Native {
181	+        messages.sort_by(|left, right| {
182	+            source_line(left.message.options())
183	+                .cmp(&source_line(right.message.options()))
184	+                .then_with(|| left.message.timestamp().cmp(&right.message.timestamp()))
185	+                .then_with(|| left.message.id().cmp(right.message.id()))
186	+        });
187	+    } else {
188	+        messages.sort_by(|left, right| {
189	+            left.message
190	+                .timestamp()
191	+                .cmp(&right.message.timestamp())
192	+                .then_with(|| left.message.id().cmp(right.message.id()))
193	+        });
194	+    }
195	+    let mut records = Vec::with_capacity(messages.len());
196	+    let mut parent_uuid = None::<String>;
197	+    for message in &messages {
198	+        if fidelity == RestoreFidelity::Native
199	+            && let Some(raw) = raw_record(message.message.options())
200	+        {
201	+            parent_uuid = raw
202	+                .get("uuid")
203	+                .and_then(Value::as_str)
204	+                .map(ToOwned::to_owned)
205	+                .or(parent_uuid);
206	+            records.push(raw);
207	+            continue;
208	+        }
209	+        let record = claude_record(session, message, parent_uuid.as_deref());
210	+        parent_uuid = record
211	+            .get("uuid")
212	+            .and_then(Value::as_str)
213	+            .map(ToOwned::to_owned);
214	+        records.push(record);
215	+    }
216	+
217	+    let mut files = vec![RestoredFile {
218	+        relative_path: claude_relative_path(session),
219	+        bytes: jsonl_bytes(&records)?,
220	+    }];
221	+    if session.session.parent_session_id.is_some()
222	+        && let Some(meta) = subagent_meta_record(session)
223	+    {
224	+        let mut meta_path = files[0].relative_path.clone();
225	+        meta_path.set_extension("meta.json");
226	+        files.push(RestoredFile {
227	+            relative_path: meta_path,
228	+            bytes: serde_json::to_vec(&meta).map_err(|err| {
229	+                AdapterError::schema(
230	+                    NAME,
231	+                    &session.session.id,
232	+                    format!("json encode failed: {err}"),
233	+                )
234	+            })?,
235	+        });
236	+    }
237	+    Ok(files)
238	+}
