240	+fn claude_relative_path(session: &crate::sessions::SessionWithMessages) -> PathBuf {
241	+    let encoded_project = session
242	+        .session
243	+        .options
244	+        .get("source")
245	+        .and_then(|source| source.get("project_dir"))
246	+        .and_then(Value::as_str)
247	+        .map(ToOwned::to_owned)
248	+        .unwrap_or_else(|| encode_project(&session.session.project));
249	+    if let Some(parent) = &session.session.parent_session_id {
250	+        let agent = session
251	+            .session
252	+            .id
253	+            .rsplit('/')
254	+            .next()
255	+            .unwrap_or(&session.session.id);
256	+        return PathBuf::from(encoded_project)
257	+            .join(parent)
258	+            .join("subagents")
259	+            .join(format!("{agent}.jsonl"));
260	+    }
261	+    PathBuf::from(encoded_project).join(format!("{}.jsonl", session.session.id))
262	+}
