282	+
283	+fn claude_record(
284	+    session: &crate::sessions::SessionWithMessages,
285	+    message: &crate::sessions::MessageWithParts,
286	+    parent_uuid: Option<&str>,
287	+) -> Value {
288	+    let role = message.message.role().as_str();
289	+    let content = claude_content(message);
290	+    json!({
291	+        "parentUuid": parent_uuid,
292	+        "isSidechain": false,
293	+        "userType": "external",
294	+        "cwd": &*session.session.project,
295	+        "sessionId": session.session.options
296	+            .get("subagent")
297	+            .and_then(|v| v.get("raw_session_id"))
298	+            .and_then(Value::as_str)
299	+            .unwrap_or(&session.session.id),
300	+        "version": session.session.options
301	+            .get("source")
302	+            .and_then(|v| v.get("version"))
303	+            .cloned()
304	+            .unwrap_or(Value::Null),
305	+        "type": role,
306	+        "message": {
307	+            "role": role,
308	+            "content": content,
309	+        },
310	+        "uuid": message.message.id(),
311	+        "timestamp": message.message.timestamp().to_rfc3339_opts(SecondsFormat::Millis, true),
312	+    })
313	+}
314	+
315	+fn claude_content(message: &crate::sessions::MessageWithParts) -> Value {
316	+    if matches!(message.message, Message::System { .. })
317	+        && let Some(content) = message.message.system_content()
318	+    {
319	+        return Value::String(content.to_owned());
320	+    }
321	+    Value::Array(message.parts.iter().map(claude_part).collect())
322	+}
