324	+fn claude_part(part: &Part) -> Value {
325	+    match &part.kind {
326	+        PartKind::Text { text } => json!({"type": "text", "text": extracted_text(text)}),
327	+        PartKind::Reasoning { text } => {
328	+            json!({"type": "thinking", "thinking": extracted_text(text)})
329	+        }
330	+        PartKind::ToolCall {
331	+            call_id,
332	+            name,
333	+            params,
334	+            provider_executed,
335	+        } => json!({
336	+            "type": if *provider_executed { "server_tool_use" } else { "tool_use" },
337	+            "id": extracted_text(call_id),
338	+            "name": extracted_text(name),
339	+            "input": params,
340	+        }),
341	+        PartKind::ToolResult {
342	+            call_id,
343	+            is_failure,
344	+            result,
345	+            ..
346	+        } => json!({
347	+            "type": "tool_result",
348	+            "tool_use_id": extracted_text(call_id),
349	+            "is_error": is_failure,
350	+            "content": result,
351	+        }),
352	+        PartKind::File {
353	+            media_type,
354	+            file_name,
355	+            data,
356	+        } => json!({
357	+            "type": "file",
358	+            "media_type": media_type,
359	+            "file_name": file_name,
360	+            "source": file_source(data),
361	+        }),
362	+        other => {
363	+            json!({"type": "text", "text": compact_json(&serde_json::to_value(other).unwrap_or(Value::Null))})
364	+        }
365	+    }
366	+}
