91	/// Live, configured adapter instance. Holds whatever handle the source needs
92	/// (an open directory root, an HTTP client + auth, a database connection)
93	/// for the lifetime of its event stream.
94	pub trait Adapter: Send + Sync {
95	    /// Stream every canonical event for every session this adapter knows
96	    /// about, in append-only order per session. The stream borrows `self`
97	    /// so callers can pass `&adapter` or hold a `Box<dyn Adapter>` and
98	    /// invoke this through `as_ref()`.
99	    fn events(&self) -> EventStream<'_> {
100	        let stream = self.events_with(&NoopOracle);
101	        Box::pin(stream.filter_map(|res| match res {
102	            Ok(AdapterYield::Event(event)) => Some(Ok(event)),
103	            Ok(AdapterYield::Skipped { .. }) => None,
104	            Err(error) => Some(Err(error)),
105	        }))
106	    }
107	
108	    /// Count how many sessions [`Self::events`] will produce, used by the
109	    /// CLI bar to set its length up front. A filesystem adapter walks its
110	    /// root and counts `.jsonl` files; an API adapter calls its list
111	    /// endpoint. Cheap and best-effort: errors here only mean we run with
112	    /// an unknown total (the bar still ticks per session), so callers
113	    /// fall back to a rolling counter rather than failing the sync.
114	    fn discover(&self) -> DiscoverFuture<'_>;
115	
116	    /// Stream events with a [`SkipOracle`] the adapter MAY consult to
117	    /// short-circuit per-session re-decoding (spec.md#event-ordering). Default impl
118	    /// ignores the oracle.
119	    fn events_with<'a>(&'a self, oracle: &'a dyn SkipOracle) -> AdapterYieldStream<'a>;
120	}
121	
122	/// Per-session watermark lookup: when did pond last write this session?
123	/// Backed by Lance's `_row_last_updated_at_version` joined to the manifest
124	/// commit timestamp (spec.md#event-ordering). Adapter compares this to the source
125	/// file's mtime to decide whether to re-decode.
126	pub trait SkipOracle: Send + Sync {
127	    fn last_ingested_at(&self, session_id: &str) -> Option<DateTime<Utc>>;
128	}
