348	/// Path-bearing io error used internally by [`collect_jsonl_files`]; callers
349	/// remap it into the right [`AdapterError`] with their adapter name.
350	pub(crate) struct IoAtPath {
351	    pub path: String,
352	    pub source: std::io::Error,
353	}
354	
355	/// Walk `root` recursively and collect every `*.jsonl` file under it, sorted
356	/// for deterministic ingest order. Shared between the file-tree adapters
357	/// (claude-code, codex-cli, pi, nanoclaw, openclaw); fan-out tree adapters
358	/// (opencode) and file-pair adapters (claude-app) walk their own shapes.
359	pub(crate) async fn collect_jsonl_files(root: &Path) -> Result<Vec<PathBuf>, IoAtPath> {
360	    use std::ffi::OsStr;
361	
362	    let mut paths = Vec::new();
363	    let mut stack = vec![root.to_path_buf()];
364	    while let Some(dir) = stack.pop() {
365	        let dir_display = dir.display().to_string();
366	        let mut entries = tokio::fs::read_dir(&dir).await.map_err(|source| IoAtPath {
367	            path: dir_display.clone(),
368	            source,
369	        })?;
370	        while let Some(entry) = entries.next_entry().await.map_err(|source| IoAtPath {
371	            path: dir_display.clone(),
372	            source,
373	        })? {
374	            let file_type = entry.file_type().await.map_err(|source| IoAtPath {
375	                path: dir_display.clone(),
376	                source,
377	            })?;
378	            let child = entry.path();
379	            if file_type.is_dir() {
380	                stack.push(child);
381	            } else if child.extension() == Some(OsStr::new("jsonl")) {
382	                paths.push(child);
383	            }
384	        }
385	    }
386	    paths.sort();
387	    Ok(paths)
388	}
