442	/// Probe every registered factory (or just the one named in `focus`) under
443	/// the current environment and shape results into [`Candidate`]s for the
444	/// picker. Returns an empty list when no factory's `probe_default` returned
445	/// anything - the caller surfaces a "configure manually" error in that case.
446	pub fn discover(focus: Option<&str>) -> Vec<Candidate> {
447	    let Some(env) = Env::from_env() else {
448	        return Vec::new();
449	    };
450	    let candidates: Vec<Candidate> = match focus {
451	        None => probe_all(&env)
452	            .into_iter()
453	            .map(|(name, config)| Candidate {
454	                name: name.to_owned(),
455	                hint: hint_for(&config),
456	                config,
457	            })
458	            .collect(),
459	        Some(name) => by_name(name)
460	            .and_then(|factory| factory.probe_default(&env))
461	            .map(|config| Candidate {
462	                name: name.to_owned(),
463	                hint: hint_for(&config),
464	                config,
465	            })
466	            .into_iter()
467	            .collect(),
468	    };
469	    candidates
470	}
