472	/// Best-effort label for the picker. For filesystem configs that's the
473	/// `path`; for richer configs we fall back to a compact JSON dump so the
474	/// operator at least sees what they're confirming.
475	fn hint_for(config: &Value) -> String {
476	    if let Some(path) = config.get("path").and_then(Value::as_str) {
477	        return path.to_owned();
478	    }
479	    if let Some(endpoint) = config.get("endpoint").and_then(Value::as_str) {
480	        return endpoint.to_owned();
481	    }
482	    serde_json::to_string(config).unwrap_or_default()
483	}
