485	/// Prompt the operator to pick which `candidates` to register, then persist
486	/// the chosen entries to `config.toml` and return them. Pre-checks every
487	/// candidate (the operator already opted in by running `pond sync`). When
488	/// `stdin_is_tty` is false we never prompt - we bail with a clear "configure
489	/// manually" message so CI and post-install scripts get a predictable error
490	/// instead of a hang. The caller injects TTY-ness so tests can drive the
491	/// non-tty branch deterministically regardless of how `cargo test` is invoked.
492	pub fn prompt_and_persist(
493	    config_path: &Path,
494	    candidates: &[Candidate],
495	    stdin_is_tty: bool,
496	) -> anyhow::Result<Vec<Candidate>> {
497	    if candidates.is_empty() {
498	        bail!(
499	            "no adapter sources detected in this environment; known adapters: {}",
500	            known_names().join(", "),
501	        );
502	    }
503	    if !stdin_is_tty {
504	        bail!(
505	            "[sources] is empty and stdin is not a terminal; add a [sources.<adapter>] \
506	             entry to {} (known adapters: {})",
507	            config_path.display(),
508	            known_names().join(", "),
509	        );
510	    }
511	    let labels = candidates
512	        .iter()
513	        .map(|c| format!("{} ({})", c.name, c.hint))
514	        .collect::<Vec<_>>();
515	    let defaults = vec![true; candidates.len()];
516	    let selections = MultiSelect::with_theme(&ColorfulTheme::default())
517	        .with_prompt("Select sources to register (space toggles, enter confirms)")
518	        .items(&labels)
519	        .defaults(&defaults)
520	        .interact()
521	        .context("source picker prompt failed")?;
522	    if selections.is_empty() {
523	        bail!("no sources selected; nothing to sync");
524	    }
525	    let picks: Vec<Candidate> = selections
526	        .into_iter()
527	        .filter_map(|index| candidates.get(index).cloned())
528	        .collect();
529	    persist(config_path, &picks)?;
530	    Ok(picks)
531	}
532	
533	/// Write the picked sources back to `config.toml` under `[sources.<name>]`,
534	/// preserving any existing user comments/formatting via `toml_edit`. Each
535	/// pick's `config` JSON object is unpacked into TOML key/value pairs.
536	fn persist(config_path: &Path, picks: &[Candidate]) -> anyhow::Result<()> {
537	    if let Some(parent) = config_path.parent() {
538	        std::fs::create_dir_all(parent)
539	            .with_context(|| format!("failed to create config dir {}", parent.display()))?;
540	    }
541	    let existing = if config_path.exists() {
542	        std::fs::read_to_string(config_path)
543	            .with_context(|| format!("failed to read {}", config_path.display()))?
544	    } else {
545	        String::new()
546	    };
547	    let mut doc: DocumentMut = existing
548	        .parse()
549	        .with_context(|| format!("failed to parse {} as TOML", config_path.display()))?;
550	
551	    if !doc.contains_key("sources") {
552	        let mut table = Table::new();
553	        table.set_implicit(true);
554	        doc.insert("sources", Item::Table(table));
555	    }
556	    let Some(sources) = doc["sources"].as_table_mut() else {
557	        bail!("config.toml has a `sources` value that is not a table");
558	    };
559	    for pick in picks {
560	        let entry = json_to_toml_table(&pick.config).with_context(|| {
561	            format!(
562	                "pick for {:?} did not produce a TOML-shaped table",
563	                pick.name
564	            )
565	        })?;
566	        sources.insert(&pick.name, Item::Table(entry));
567	    }
568	
569	    std::fs::write(config_path, doc.to_string())
570	        .with_context(|| format!("failed to write {}", config_path.display()))?;
571	    Ok(())
572	}
573	
574	/// Convert a JSON object into a `toml_edit::Table`. Factories produce JSON
575	/// blobs (the seam contract); the picker persists them as TOML tables. Non-
576	/// object roots are rejected with an error rather than silently dropped.
577	fn json_to_toml_table(value: &Value) -> anyhow::Result<Table> {
578	    let Value::Object(map) = value else {
579	        bail!("config blob must be a JSON object, got {value}");
580	    };
581	    let mut table = Table::new();
582	    for (key, val) in map {
583	        table[key] = json_to_toml_item(val)?;
584	    }
585	    Ok(table)
586	}
587	
588	fn json_to_toml_item(value: &Value) -> anyhow::Result<Item> {
589	    use toml_edit::{Array, InlineTable, Value as TomlValue, value as tv};
590	    Ok(match value {
591	        Value::Null => bail!("null is not representable in TOML"),
592	        Value::Bool(b) => tv(*b),
593	        Value::Number(n) => {
594	            if let Some(i) = n.as_i64() {
595	                tv(i)
596	            } else if let Some(f) = n.as_f64() {
597	                tv(f)
598	            } else {
599	                bail!("number {n} is not representable in TOML");
600	            }
601	        }
602	        Value::String(s) => tv(s.clone()),
603	        Value::Array(values) => {
604	            let mut array = Array::new();
605	            for v in values {
606	                let item = json_to_toml_item(v)?;
607	                let toml_value: TomlValue = item.into_value().map_err(|_| {
608	                    anyhow::anyhow!("array element {v} is not a scalar; nested tables in arrays")
609	                })?;
610	                array.push(toml_value);
611	            }
612	            Item::Value(TomlValue::Array(array))
613	        }
614	        Value::Object(_) => {
615	            let table = json_to_toml_table(value)?;
616	            let mut inline = InlineTable::new();
617	            for (key, item) in table.iter() {
618	                if let Some(v) = item.as_value() {
619	                    inline.insert(key, v.clone());
620	                }
621	            }
622	            Item::Value(TomlValue::InlineTable(inline))
623	        }
624	    })
625	}
