93	
94	    fn serialize(
95	        &self,
96	        session: &crate::sessions::SessionWithMessages,
97	        fidelity: RestoreFidelity,
98	    ) -> Result<Vec<RestoredFile>, AdapterError> {
99	        serialize_session(session, fidelity)
100	    }
