102	
103	fn serialize_session(
104	    session: &crate::sessions::SessionWithMessages,
105	    fidelity: RestoreFidelity,
106	) -> Result<Vec<RestoredFile>, AdapterError> {
107	    let mut messages = session.messages.clone();
108	    if fidelity == RestoreFidelity::Native {
109	        messages.sort_by(|left, right| {
110	            source_line(left.message.options())
111	                .cmp(&source_line(right.message.options()))
112	                .then_with(|| left.message.timestamp().cmp(&right.message.timestamp()))
113	                .then_with(|| left.message.id().cmp(right.message.id()))
114	        });
115	    } else {
116	        messages.sort_by(|left, right| {
117	            left.message
118	                .timestamp()
119	                .cmp(&right.message.timestamp())
120	                .then_with(|| left.message.id().cmp(right.message.id()))
121	        });
122	    }
123	    let mut records = Vec::with_capacity(messages.len());
124	    let mut parent_uuid = None::<String>;
125	    for message in &messages {
126	        if fidelity == RestoreFidelity::Native
127	            && let Some(raw) = raw_record(message.message.options())
128	        {
129	            parent_uuid = raw
130	                .get("uuid")
131	                .and_then(Value::as_str)
132	                .map(ToOwned::to_owned)
133	                .or(parent_uuid);
134	            records.push(raw);
135	            continue;
136	        }
137	        let record = claude_record(session, message, parent_uuid.as_deref());
138	        parent_uuid = record
139	            .get("uuid")
140	            .and_then(Value::as_str)
141	            .map(ToOwned::to_owned);
142	        records.push(record);
143	    }
144	
145	    let mut files = vec![RestoredFile {
146	        relative_path: claude_relative_path(session),
147	        bytes: jsonl_bytes(&records)?,
148	    }];
149	    if session.session.parent_session_id.is_some()
150	        && let Some(meta) = subagent_meta_record(session)
151	    {
152	        let mut meta_path = files[0].relative_path.clone();
153	        meta_path.set_extension("meta.json");
154	        files.push(RestoredFile {
155	            relative_path: meta_path,
156	            bytes: serde_json::to_vec(&meta).map_err(|err| {
157	                AdapterError::schema(
158	                    NAME,
159	                    &session.session.id,
160	                    format!("json encode failed: {err}"),
161	                )
162	            })?,
163	        });
164	    }
165	    Ok(files)
166	}
167	
168	fn claude_relative_path(session: &crate::sessions::SessionWithMessages) -> PathBuf {
169	    let encoded_project = session
170	        .session
171	        .options
172	        .get("source")
173	        .and_then(|source| source.get("project_dir"))
174	        .and_then(Value::as_str)
175	        .map(ToOwned::to_owned)
176	        .unwrap_or_else(|| encode_project(&session.session.project));
177	    if let Some(parent) = &session.session.parent_session_id {
178	        let agent = session
179	            .session
180	            .id
181	            .rsplit('/')
182	            .next()
183	            .unwrap_or(&session.session.id);
184	        return PathBuf::from(encoded_project)
185	            .join(parent)
186	            .join("subagents")
187	            .join(format!("{agent}.jsonl"));
188	    }
189	    PathBuf::from(encoded_project).join(format!("{}.jsonl", session.session.id))
190	}
191	
192	fn source_line(options: &ProviderOptions) -> Option<u64> {
193	    options
194	        .get("source")
195	        .and_then(|source| source.get("line"))
196	        .and_then(Value::as_u64)
197	}
198	
199	fn encode_project(project: &str) -> String {
200	    project.replace(['/', '.'], "-")
201	}
202	
203	fn subagent_meta_record(session: &crate::sessions::SessionWithMessages) -> Option<Value> {
204	    let subagent = session.session.options.get("subagent")?;
205	    Some(json!({
206	        "agentType": subagent.get("agent_type"),
207	        "description": subagent.get("description"),
208	    }))
209	}
210	
211	fn claude_record(
212	    session: &crate::sessions::SessionWithMessages,
213	    message: &crate::sessions::MessageWithParts,
214	    parent_uuid: Option<&str>,
215	) -> Value {
216	    let role = message.message.role().as_str();
217	    let content = claude_content(message);
218	    json!({
219	        "parentUuid": parent_uuid,
220	        "isSidechain": false,
221	        "userType": "external",
222	        "cwd": &*session.session.project,
223	        "sessionId": session.session.options
224	            .get("subagent")
225	            .and_then(|v| v.get("raw_session_id"))
226	            .and_then(Value::as_str)
227	            .unwrap_or(&session.session.id),
228	        "version": session.session.options
229	            .get("source")
230	            .and_then(|v| v.get("version"))
231	            .cloned()
232	            .unwrap_or(Value::Null),
233	        "type": role,
234	        "message": {
235	            "role": role,
236	            "content": content,
237	        },
238	        "uuid": message.message.id(),
239	        "timestamp": message.message.timestamp().to_rfc3339_opts(SecondsFormat::Millis, true),
240	    })
241	}
242	
243	fn claude_content(message: &crate::sessions::MessageWithParts) -> Value {
244	    if matches!(message.message, Message::System { .. })
245	        && let Some(content) = message.message.system_content()
246	    {
247	        return Value::String(content.to_owned());
248	    }
249	    Value::Array(message.parts.iter().map(claude_part).collect())
250	}
251	
252	fn claude_part(part: &Part) -> Value {
253	    match &part.kind {
254	        PartKind::Text { text } => json!({"type": "text", "text": extracted_text(text)}),
255	        PartKind::Reasoning { text } => {
256	            json!({"type": "thinking", "thinking": extracted_text(text)})
257	        }
258	        PartKind::ToolCall {
259	            call_id,
260	            name,
261	            params,
262	            provider_executed,
263	        } => json!({
264	            "type": if *provider_executed { "server_tool_use" } else { "tool_use" },
265	            "id": extracted_text(call_id),
266	            "name": extracted_text(name),
267	            "input": params,
268	        }),
269	        PartKind::ToolResult {
270	            call_id,
271	            is_failure,
272	            result,
273	            ..
274	        } => json!({
275	            "type": "tool_result",
276	            "tool_use_id": extracted_text(call_id),
277	            "is_error": is_failure,
278	            "content": result,
279	        }),
280	        PartKind::File {
281	            media_type,
282	            file_name,
283	            data,
284	        } => json!({
285	            "type": "file",
286	            "media_type": media_type,
287	            "file_name": file_name,
288	            "source": file_source(data),
289	        }),
290	        other => {
291	            json!({"type": "text", "text": compact_json(&serde_json::to_value(other).unwrap_or(Value::Null))})
292	        }
293	    }
294	}
295	
296	fn file_source(data: &FileData) -> Value {
297	    match data {
298	        FileData::String(value) => json!({"type": "text", "data": value}),
299	        FileData::Bytes(value) => json!({"type": "base64", "data": value}),
300	        FileData::Url(value) => json!({"type": "url", "url": value}),
301	    }
302	}
