304	/// Configured claude-code reader. Walks a tree of `*.jsonl` files under
305	/// [`Self::root`] and yields canonical events in source order per session.
306	#[derive(Debug, Clone)]
307	pub struct ClaudeCodeAdapter {
308	    root: PathBuf,
309	}
310	
311	impl ClaudeCodeAdapter {
312	    pub fn new(root: impl Into<PathBuf>) -> Self {
313	        Self { root: root.into() }
314	    }
315	}
316	
317	impl Adapter for ClaudeCodeAdapter {
318	    fn discover(&self) -> DiscoverFuture<'_> {
319	        let root = self.root.clone();
320	        Box::pin(async move {
321	            // Count files only - do not pre-parse headers. Headers are read
322	            // once at stream time, where any decode failure is the canonical
323	            // skip path. Pre-reading here would error out twice for the same
324	            // bad file (once in discover, once in events) and would charge
325	            // every healthy file two opens instead of one.
326	            let paths = collect_jsonl_files(&root)
327	                .await
328	                .map_err(|io| AdapterError::io(NAME, io.path, io.source))?;
329	            Ok(paths.len())
330	        })
331	    }
332	
333	    fn events_with<'a>(&'a self, oracle: &'a dyn SkipOracle) -> AdapterYieldStream<'a> {
334	        let root = self.root.clone();
335	        Box::pin(stream! {
336	            let paths = match collect_jsonl_files(&root).await {
337	                Ok(paths) => paths,
338	                Err(io) => {
339	                    yield Err(AdapterError::io(NAME, io.path, io.source));
340	                    return;
341	                }
342	            };
343	            for path in paths {
344	                let path_display = path.display().to_string();
345	
346	                if let Some((id, mtime)) = peek_id_and_mtime(&path).await
