37	/// Stateless factory: opens [`CodexCliAdapter`] instances and probes for the
38	/// canonical install location under `~/.codex/sessions`.
39	pub struct CodexCliFactory;
40	
41	impl AdapterFactory for CodexCliFactory {
42	    fn name(&self) -> &'static str {
43	        NAME
44	    }
45	
46	    fn open(&self, config: Value) -> Result<Box<dyn Adapter>, AdapterError> {
47	        #[derive(Deserialize)]
48	        struct Cfg {
49	            path: PathBuf,
50	        }
51	        let cfg: Cfg = serde_json::from_value(config)
52	            .map_err(|err| AdapterError::config(NAME, format!("bad config blob: {err}")))?;
53	        let path = match std::env::var_os("HOME") {
54	            Some(home) => expand_home_under(&cfg.path, Path::new(&home)),
55	            None => cfg.path,
56	        };
57	        Ok(Box::new(CodexCliAdapter::new(path)))
58	    }
59	
60	    fn probe_default(&self, env: &Env) -> Option<Value> {
61	        let path = env.home.join(".codex").join("sessions");
62	        path.exists().then(|| json!({ "path": path }))
63	    }
64	
65	    fn serialize(
66	        &self,
67	        session: &crate::sessions::SessionWithMessages,
68	        fidelity: RestoreFidelity,
69	    ) -> Result<Vec<RestoredFile>, AdapterError> {
70	        serialize_session(session, fidelity)
71	    }
72	}
73	
74	fn serialize_session(
75	    session: &crate::sessions::SessionWithMessages,
76	    fidelity: RestoreFidelity,
77	) -> Result<Vec<RestoredFile>, AdapterError> {
78	    let mut records = Vec::new();
79	    if fidelity == RestoreFidelity::Native
80	        && let Some(raw) = raw_record(&session.session.options)
81	    {
82	        records.push(raw);
83	    } else {
84	        records.push(codex_session_meta(session));
85	    }
86	    let mut messages = session.messages.clone();
87	    messages.sort_by(|left, right| {
88	        left.message
89	            .timestamp()
90	            .cmp(&right.message.timestamp())
91	            .then_with(|| left.message.id().cmp(right.message.id()))
92	    });
93	    for message in &messages {
94	        if fidelity == RestoreFidelity::Native
95	            && let Some(raw) = raw_record(message.message.options())
96	        {
97	            records.push(raw);
98	        } else {
99	            records.push(codex_response_item(message));
100	        }
101	    }
102	    Ok(vec![RestoredFile {
103	        relative_path: codex_relative_path(session),
104	        bytes: jsonl_bytes(&records)?,
105	    }])
106	}
107	
108	fn codex_relative_path(session: &crate::sessions::SessionWithMessages) -> PathBuf {
109	    let ts = session.session.created_at;
110	    let filename_ts = ts.format("%Y-%m-%dT%H-%M-%S");
111	    PathBuf::from("sessions")
112	        .join(format!("{:04}", ts.year()))
113	        .join(format!("{:02}", ts.month()))
114	        .join(format!("{:02}", ts.day()))
115	        .join(format!(
116	            "rollout-{filename_ts}-{}.jsonl",
117	            session.session.id
118	        ))
119	}
120	
121	fn codex_session_meta(session: &crate::sessions::SessionWithMessages) -> Value {
122	    json!({
123	        "timestamp": session.session.created_at.to_rfc3339_opts(SecondsFormat::Millis, true),
124	        "type": "session_meta",
125	        "payload": {
126	            "id": session.session.id,
127	            "timestamp": session.session.created_at.to_rfc3339_opts(SecondsFormat::Millis, true),
128	            "cwd": &*session.session.project,
129	        }
130	    })
131	}
132	
133	fn codex_response_item(message: &crate::sessions::MessageWithParts) -> Value {
134	    json!({
135	        "timestamp": message.message.timestamp().to_rfc3339_opts(SecondsFormat::Millis, true),
136	        "type": "response_item",
137	        "payload": codex_payload(message),
138	    })
139	}
140	
141	fn codex_payload(message: &crate::sessions::MessageWithParts) -> Value {
142	    if let Some(part) = message.parts.first() {
143	        match &part.kind {
144	            PartKind::ToolCall {
145	                call_id,
146	                name,
147	                params,
148	                ..
149	            } if matches!(message.message, Message::Assistant { .. }) => {
150	                return json!({
151	                    "type": "function_call",
152	                    "call_id": extracted_text(call_id),
153	                    "name": extracted_text(name),
154	                    "arguments": compact_json(params),
155	                });
156	            }
157	            PartKind::ToolResult {
158	                call_id, result, ..
159	            } if matches!(message.message, Message::Tool { .. }) => {
160	                return json!({
161	                    "type": "function_call_output",
162	                    "call_id": extracted_text(call_id),
163	                    "output": result,
164	                });
165	            }
166	            PartKind::Reasoning { text }
167	                if matches!(message.message, Message::Assistant { .. }) =>
168	            {
169	                if let Some(text) = text
170	                    && let Ok(value) = serde_json::from_str::<Value>(text.as_ref())
171	                {
172	                    return value;
173	                }
174	                return json!({
175	                    "type": "reasoning",
176	                    "summary": [{"type": "summary_text", "text": extracted_text(text)}],
177	                });
178	            }
179	            _ => {}
180	        }
181	    }
182	    json!({
183	        "type": "message",
184	        "role": match message.message.role() {
185	            crate::wire::Role::System => "developer",
186	            crate::wire::Role::User => "user",
187	            crate::wire::Role::Assistant => "assistant",
188	            crate::wire::Role::Tool => "tool",
189	        },
190	        "content": message.parts.iter().map(codex_content_part).collect::<Vec<_>>(),
191	    })
192	}
193	
194	fn codex_content_part(part: &Part) -> Value {
195	    match &part.kind {
196	        PartKind::Text { text } => json!({
197	            "type": "input_text",
198	            "text": extracted_text(text),
199	        }),
200	        PartKind::File { data, .. } => json!({
201	            "type": "input_text",
202	            "text": match data {
203	                crate::wire::FileData::String(value) => value.clone(),
204	                crate::wire::FileData::Bytes(value) => format!("<{} bytes>", value.len()),
205	                crate::wire::FileData::Url(value) => value.clone(),
206	            },
207	        }),
208	        other => json!({
209	            "type": "input_text",
210	            "text": compact_json(&serde_json::to_value(other).unwrap_or(Value::Null)),
211	        }),
212	    }
213	}
